preConditionHook:
// MA SIDE FLIP RUN (Brian's notes P5): last recentBars closes above the
// EMA, the priorBars closes before them below it (long); short mirrored.
// MultiWalk's WFSafe_Xaverage, ported unchanged from EmaGapBar (the EMA
// reference, with the measurements): price seed on the first calculated bar
// (ctx.CurrentBar() == 1), recurrence x + sf*(p - x) in ONE statement,
// sf = 2/(Length+1) from the raw input every bar, state carried on a length
// change (EL_XAverage_Lag_Probe.txt, 2026-09-17).
emaSf = 2.0 / (emaLength + 1.0);
if (ctx.CurrentBar() == 1) {
    emaVal = close[0];
} else {
    emaVal = emaVal + emaSf * (close[0] - emaVal);
}
// LAGGED EMA READS (MEASURED, XAVERAGE_LAG_FINDINGS.md): ema[k] is bit for
// bit the value k bars earlier and reads 0.0 before that history exists, so
// the zero-initialized ring buffer below is exact and the rule guards its
// first k bars on the bar counter instead of comparing against the zero.
// Re-seeded if the depth changes.
emaDepth = (int)recentBars + (int)priorBars;
if (emaDepth < 1) {
    emaDepth = 1;
}
if (emaHistory.size() != (std::size_t)emaDepth) {
    emaHistory.assign((std::size_t)emaDepth, 0.0);
    emaCursor = 0;
}
emaHistory[emaCursor] = emaVal;
upNow = 0;
downNow = 0;
upBefore = 0;
downBefore = 0;
for (int ii = 0; ii <= (int)recentBars - 1; ++ii) {
    double lagged = emaHistory[(emaCursor + emaHistory.size() - (std::size_t)(ii)) % emaHistory.size()];
    if (el_gt(close[ii], lagged)) {
        upNow = upNow + 1;
    }
    if (el_lt(close[ii], lagged)) {
        downNow = downNow + 1;
    }
}
for (int ii = (int)recentBars; ii <= (int)recentBars + (int)priorBars - 1; ++ii) {
    double lagged = emaHistory[(emaCursor + emaHistory.size() - (std::size_t)(ii)) % emaHistory.size()];
    if (el_gt(close[ii], lagged)) {
        upBefore = upBefore + 1;
    }
    if (el_lt(close[ii], lagged)) {
        downBefore = downBefore + 1;
    }
}
emaCursor = (emaCursor + 1) % emaHistory.size();
flipReady = ctx.CurrentBar() > (int)recentBars + (int)priorBars - 1;
